 anatomy:['Heart anatomy',O+'19-1-heart-anatomy'], conduction:['Cardiac electrical activity',O+'19-2-cardiac-muscle-and-electrical-activity'], cycle:['Cardiac cycle',O+'19-3-cardiac-cycle'], output:['Cardiac physiology',O+'19-4-cardiac-physiology'], flow:['Blood flow and resistance',O+'20-2-blood-flow-blood-pressure-and-resistance'], circuit:['Circulatory pathways',O+'20-5-circulatory-pathways'], lung:['The lungs',O+'22-2-the-lungs'], breathing:['The process of breathing',O+'22-3-the-process-of-breathing'], exchange:['Gas exchange',O+'22-4-gas-exchange'], transport:['Transport of gases',O+'22-5-transport-of-gases'], space:['NCBI Bookshelf · Lung dead space','https://www.ncbi.nlm.nih.gov/books/NBK482501/'], oxygen:['NCBI Bookshelf · Oxygen transport','https://www.ncbi.nlm.nih.gov/books/NBK54103/'],  aamc:['AAMC · MCAT content outline, category 3B','https://students-residents.aamc.org/media/9261/download?attachment='], retrieval:['Karpicke & Blunt · Retrieval practice (2011)','https://pubmed.ncbi.nlm.nih.gov/21252317/'], spacing:['Cepeda et al. · Distributed practice (2006)','https://pubmed.ncbi.nlm.nih.gov/16719566/']
