function lesson(id,title,tier,goal,steps,checks,refs){return {id,title,tier,goal,steps,checks,refs}}
const lessons=[
 lesson('two-circuits','Follow one red blood cell',0,'Trace both circuits and identify where oxygen enters and leaves blood.',[
 ['Right heart to lung','The right ventricle ejects through the pulmonary valve into the pulmonary trunk. Pulmonary arteries direct blood toward capillaries alongside the alveoli.','heart|pulmonary-trunk'],
 ['Lung to left heart','Pulmonary venules and veins collect blood from exchange regions and return it to the left atrium. Blood crosses the mitral valve as it enters the left ventricle.','heart|left-atrium'],
 ['Through the body','The left ventricle ejects through the aortic valve. Systemic arteries deliver blood to tissues. From the intestine, venous blood passes through a second capillary bed in the liver before returning to the heart.','vessels|hepatic-portal-vein']],
 [['Which valve does blood cross first between the right atrium and pulmonary trunk?','Trace the chambers in flow order.','The tricuspid valve. Blood next reaches the right ventricle and then crosses the pulmonary valve.'],['Name the two capillary beds linked by the portal route from the small intestine.','Start where nutrients enter blood.','Intestinal capillaries, then hepatic sinusoids. The hepatic portal vein connects these beds.']],['anatomy','circuit']),
 lesson('valve-timing','Read the valves through a heartbeat',0,'Predict valve position from the pressures on its two sides.',[
 ['Fill the ventricle','When left atrial pressure exceeds left ventricular pressure, the mitral valve opens. Blood enters the ventricle while the aortic valve is closed.','heart|mitral-valve'],
 ['Build pressure','As left ventricular pressure rises above atrial pressure the mitral valve closes. Both valves are closed during isovolumetric contraction. Volume stays essentially constant.','heart|left-ventricle'],
 ['Eject and relax','The aortic valve opens when ventricular pressure exceeds aortic pressure. Reversal of that gradient near the end of ejection leads to closure.','heart|aortic-valve']],
 [['How do pressure and volume change during isovolumetric contraction?','Account for flow across both valves.','Pressure rises while volume stays nearly constant.'],['Ventricular pressure has fallen below aortic pressure but remains above left atrial pressure after ejection. Which left-sided valve is open?','Place this interval between ejection and filling.','Neither. During isovolumetric relaxation the aortic valve has closed and the mitral valve has yet to open.']],['cycle','anatomy']),
 lesson('conduction','Connect the ECG to contraction',0,'Relate atrial and ventricular electrical events to their mechanical consequences.',[
 ['Initiate atrial activation','The sinoatrial node normally initiates activation. Atrial depolarization produces the P wave. Atrial contraction follows the electrical event.','heart|sinoatrial-node'],
 ['Delay the signal','Slow conduction through the atrioventricular node allows time for atrial contraction before ventricular systole. The PR interval also includes conduction outside the node.','heart|atrioventricular-node'],
 ['Activate the ventricles','The AV bundle, bundle branches and Purkinje fibers help coordinate ventricular activation. Ventricular depolarization produces the QRS complex. Ventricular repolarization produces the T wave.','heart|purkinje-fibers']],
 [['What electrical event produces the QRS complex?','Name a chamber group and a change in membrane potential.','Ventricular depolarization. Pressure generation follows activation.'],['Why is AV nodal delay important for filling?','Think about contraction order.','It permits atrial contraction before ventricular pressure rises enough to close the atrioventricular valves.']],['conduction','cycle']),
 lesson('lung-map','Navigate the airway into an alveolus',0,'Identify the conducting and respiratory zones in sequence.',[
 ['Orient at the carina','At the carina the trachea divides into main bronchi. Lobar branches then give rise to segmental bronchi. The right lung usually has three lobes and the left two.','lungs|carina'],
 ['Find the transition','Terminal bronchioles are the final conducting branches. Respiratory bronchioles have scattered alveoli in their walls and can participate in gas exchange.','alveoli|terminal-bronchiole'],
 ['Cross the septum','Along the thin side of an alveolar septum, oxygen passes through the surface lining, type I epithelium, basal laminae and capillary endothelium before entering blood.','alveoli|respiratory-membrane']],
 [['What distinguishes a respiratory bronchiole from a terminal bronchiole?','Examine the wall.','Alveoli open in the wall of a respiratory bronchiole. Terminal bronchioles occupy the conducting zone.'],['Which cell makes surfactant and how does surfactant affect alveoli?','Separate the producer from the thin exchange surface.','Type II cells produce surfactant. It reduces air–liquid surface tension and helps stabilize alveoli.']],['lung','exchange','breathing']),
 lesson('venous-return','Compare three routes of venous return',0,'Distinguish systemic, myocardial and pulmonary venous drainage.',[
 ['Deep leg','Deep veins return blood toward the popliteal and femoral veins. At the inguinal ligament the femoral vein continues as the external iliac vein. Skeletal muscle contraction and competent valves assist return.','vessels|femoral-vein'],
 ['Myocardium','The great cardiac vein carries myocardial venous blood toward the coronary sinus, which opens into the right atrium. Some cardiac veins drain separately.','heart|coronary-sinus'],
 ['Lungs','Pulmonary veins carry blood from the lungs to the left atrium. A vein is named for its direction of flow toward the heart. Pulmonary venous blood is normally oxygen-rich.','lungs|right-superior-pulmonary-vein']],
 [['Where does the coronary sinus open?','Follow myocardial venous blood.','Into the right atrium. The tricuspid valve is the next valve along this route.'],['Which usually has higher oxygen content, a pulmonary vein or a vein leaving exercising muscle?','Consider what occurred in the preceding capillary bed.','The pulmonary vein. Blood has gained oxygen in pulmonary capillaries, while exercising muscle extracted oxygen from systemic capillaries.']],['anatomy','circuit','flow']),
 lesson('pressure-flow','Predict flow from pressure and resistance',1,'Predict how the pressure gradient and vessel radius affect steady flow.',[
 ['Specify both ends','Flow through a bed equals the inlet-to-outlet pressure difference divided by resistance at steady state. A change in one pressure alone does not specify the gradient.','vessels|renal-artery'],
 ['Change radius','For steady laminar flow of a Newtonian fluid in a rigid cylindrical tube, resistance is inversely proportional to the fourth power of radius. Pulsatility and compliant vessels limit this approximation in life.','vessels|radial-artery'],
 ['Compare gradients','For a given resistance, doubling the inlet-to-outlet pressure difference doubles the modeled flow. At the same gradient, doubling resistance halves flow.','lungs|right-pulmonary-artery']],
 [['In an ideal tube, radius doubles with gradient, length and viscosity fixed. What happens to flow?','Use the fourth power.','Resistance falls to 1/16, so flow rises sixteenfold.'],['Both inlet and outlet pressure increase by 5 mmHg. Resistance stays fixed. What happens to modeled flow?','Subtract the two pressures before and after.','Flow stays the same because the pressure gradient is unchanged.']],['flow','output']),
 lesson('stroke-output','Calculate what one beat delivers',1,'Calculate stroke volume, ejection fraction and cardiac output from measurements.',[
 ['Measure the volume change','End-diastolic volume is the ventricular volume at the end of filling. Subtract the end-systolic volume to obtain stroke volume.','heart|left-ventricle'],
 ['Find the fraction','Ejection fraction equals stroke volume divided by end-diastolic volume. A ventricle can eject a large percentage of a small starting volume and still have a small stroke volume.','heart|aortic-valve'],
 ['Scale to a minute','Heart rate in beats/min multiplied by stroke volume in mL/beat gives mL/min. Divide by 1,000 for L/min.','heart|aorta']],
 [['EDV is 140 mL and ESV is 70 mL. What are stroke volume and ejection fraction?','Subtract, then divide by the starting volume.','Stroke volume is 70 mL. Ejection fraction is 70/140 × 100 = 50%.'],['Heart rate is 75/min and stroke volume is 64 mL. What is cardiac output?','Cancel the beat unit.','75 × 64 = 4,800 mL/min, or 4.8 L/min.']],['cycle','output']),
 lesson('ventilation','Compare two breathing patterns',1,'Distinguish minute ventilation and alveolar ventilation at different depths and rates.',[
 ['Move air','During spontaneous inspiration the diaphragm contracts and descends. With an open airway, increasing thoracic volume lowers alveolar pressure below atmospheric pressure and air enters.','lungs|diaphragm'],
 ['Account for dead space','Minute ventilation equals tidal volume times respiratory rate. Conducting airways contribute anatomical dead space. Ventilated alveoli with insufficient perfusion can add alveolar dead space.','lungs|trachea'],
 ['Compare effective ventilation','Using the supplied dead-space estimate, alveolar ventilation equals (tidal volume − dead space per breath) × respiratory rate. Keep the units consistent.','alveoli|respiratory-bronchiole']],
 [['At 12 breaths/min, tidal volume 500 mL and dead space 150 mL, calculate minute and alveolar ventilation.','Include all air first, then subtract dead space.','Minute ventilation is 6.0 L/min. Alveolar ventilation is (500 − 150) × 12 = 4.2 L/min.'],['Rate doubles to 24/min and tidal volume falls to 250 mL. Dead space remains 150 mL. Calculate alveolar ventilation.','Find fresh air per breath first.','(250 − 150) × 24 = 2.4 L/min, although total minute ventilation remains 6.0 L/min.']],['breathing','space']),
 lesson('vq','Separate ventilation, perfusion and diffusion',1,'Distinguish a regional loss of air, blood or exchange capacity.',[
 ['Define the ratio','Regional V̇/Q̇ compares alveolar ventilation with pulmonary capillary perfusion. An obstructed airway reduces regional ventilation. An obstructed vessel reduces downstream perfusion.','alveoli|pulmonary-arteriole'],
 ['Examine the limits','With ongoing perfusion and zero ventilation, V̇/Q̇ is zero. With ventilation and zero perfusion, V̇/Q̇ approaches infinity as perfusion falls to zero. The latter region contributes to alveolar dead space.','alveoli|alveolar-capillaries'],
 ['Change the membrane','With gas properties held fixed, diffusion rate increases with exchange area and partial-pressure difference, and decreases as barrier thickness increases.','alveoli|type-i-cell']],
 [['A ventilated unit loses capillary blood flow. What happens to its V̇/Q̇ and to dead space?','Change the denominator.','The ratio rises toward infinity as perfusion approaches zero. The ventilated unit contributes to alveolar dead space.'],['What happens to initial diffusion rate if membrane thickness doubles while all other factors stay fixed?','Place thickness in the denominator.','The diffusion rate falls to one half.']],['exchange','space']),
 lesson('oxygen-delivery','Distinguish oxygen pressure from delivery',1,'Predict the effect of changing hemoglobin or blood flow with PaO₂ held constant.',[
 ['Establish a gradient','Dissolved oxygen establishes partial pressure. A partial-pressure gradient drives oxygen across the alveolar–capillary barrier. Oxygen can then bind hemoglobin.','alveoli|respiratory-membrane'],
 ['Count oxygen capacity','Approximate arterial content in mL O₂/dL as 1.34 × hemoglobin (g/dL) × saturation (fraction) + 0.003 × PaO₂ (mmHg). The first term accounts for bound oxygen.','alveoli|erythrocyte'],
 ['Deliver oxygen per minute','Multiply cardiac output in L/min by oxygen content in mL/dL and by 10 dL/L. This gives systemic delivery in mL O₂/min, before extraction by tissues.','heart|left-ventricle']],
 [['Two samples have equal PaO₂ and saturation, but Hb is 15 versus 9 g/dL. Which carries more oxygen?','Separate dissolved and bound oxygen.','The 15 g/dL sample. Its dissolved component is unchanged, but it has more hemoglobin-bound oxygen per dL.'],['Arterial content is 18 mL O₂/dL and cardiac output is 5 L/min. What is oxygen delivery?','Convert liters to deciliters.','18 × 5 × 10 = 900 mL O₂/min.']],['transport','oxygen','output'])
];
