function model(k,from){const [sys,id]=k.split('|');const n=data()[sys]?.find(e=>e.id===id)?.name||id;return '<button type="button" data-open="'+esc(k)+'" data-clfrom="'+from+'" class="cl-model">'+esc(n)+' in 3D</button>'}
