 return '<div class="cl-pills">'+btn('list','All lessons')+'<span>'+tiers[l.tier]+'</span></div>'+heading(l.title,l.goal)+'<div class="cl-columns"><div class="cl-steps">'+l.steps.map(([title,body,k],i)=>'<article><span class="cl-num">'+(i+1)+'</span><div><h4>'+esc(title)+'</h4><p>'+esc(body)+'</p>'+model(k,'lesson')+'</div></article>').join('')+'</div><aside class="cl-recall"><h4>Recall without the model</h4>'+l.checks.map(([q,h,a])=>'<div class="cl-q"><b>'+esc(q)+'</b><details><summary>Hint</summary><p>'+esc(h)+'</p></details><details><summary>Check your answer</summary><p>'+esc(a)+'</p></details></div>').join('')+btn('done',saved.done.includes(l.id)?'Mark incomplete':'Mark lesson complete','','class="cl-primary"')+'</aside></div><div class="cl-refs"><b>Read further</b>'+l.refs.map(link).join('')+'</div>';
