let bank=null;
function cards(){if(bank)return bank;bank=new Map();for(const l of lessons)l.checks.forEach(([q,h,a],i)=>bank.set(l.id+'-'+i,{d:'concepts',q,h,a,k:l.steps[i][2]}));for(const [d,list] of Object.entries(data()))for(const s of (list||[]).slice(1))bank.set(d+'|'+s.id,{d,q:'What does the '+s.name.toLowerCase()+' do?',h:s.location,a:s.role,k:d+'|'+s.id});return bank}
function start(mode,shuffle=false){
 const ids=[...cards()].filter(([id,c])=>c.d===deck&&(mode!=='missed'||saved.ratings[id]==='again')).map(([id])=>id);
 if(shuffle)for(let i=ids.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[ids[i],ids[j]]=[ids[j],ids[i]]}
 session={ids,n:0,hits:0,face:false,hint:false,mode,deck};saved.s=session;save();
}
function deckView(){
 if(!session){const s=saved.s;if(s&&owned(decks,s.deck)&&Array.isArray(s.ids)&&s.ids.every(x=>cards().get(x)?.d===s.deck)&&Number.isInteger(s.n)&&s.n>=0&&s.n<=s.ids.length){session=s;deck=s.deck}else start('all')}
 const c=cards().get(session.ids[session.n]),miss=[...cards()].filter(([i,v])=>v.d===deck&&saved.ratings[i]==='again').length;
 const controls='<div class="cl-pills"><label>Deck <select data-cldeck>'+Object.entries(decks).map(([id,t])=>'<option value="'+id+'" '+(deck===id?'selected':'')+'>'+esc(t)+'</option>').join('')+'</select></label>'+btn('full','Full deck')+btn('shuffle','Shuffle')+btn('miss','Review again ('+miss+')','',miss?'':'disabled')+'</div>';
 let card;
 if(c)card='<small>Card '+(session.n+1)+' of '+session.ids.length+'</small><progress value="'+session.n+'" max="'+session.ids.length+'" aria-label="Deck progress"></progress><h4>'+esc(c.q)+'</h4>'+(session.face?'<div class="cl-answer"><b>Answer</b><p>'+esc(c.a)+'</p>'+model(c.k,'card')+'</div><div class="cl-pills">'+btn('again','Review again')+btn('known','Got it','','class="cl-primary"')+btn('flip','Show question')+'</div>':'<div class="cl-pills">'+btn('flip','Reveal answer','','class="cl-primary"')+btn('hint',session.hint?'Hide hint':'Show hint')+'</div>'+(session.hint?'<p>'+esc(c.h)+'</p>':''));
 else card='<h4>Round complete</h4><p>'+session.hits+' of '+session.ids.length+' marked “Got it”.</p><div class="cl-pills">'+(miss?btn('miss','Practice missed cards'):'')+btn('shuffle','New shuffled round')+'</div>';
 return heading('Flashcards','Answer aloud, reveal the explanation, then rate your recall. Your deck position and ratings stay in this browser.')+controls+'<div class="cl-flash">'+card+'</div>';
}
