function guide(offline=false){
 return heading('Instructor guide','A 30-minute paired practical with direct model links and a short exit check.')+'<div class="cl-columns"><article><h4>Run the session</h4><ul><li>0–5 min · Give each pair an unlabeled study plate and ask both learners to orient right and left.</li><li>5–17 min · Choose two stations. One partner traces a route while the other checks labels. Switch roles.</li><li>17–25 min · Change a physiological variable and record a prediction before calculating.</li><li>25–30 min · Hide the models. Each learner explains one route and one consequence.</li></ul></article><article><h4>Score the explanation</h4><p>Award one point for each demonstrated skill.</p><ol><li>Locates the structure and orients it.</li><li>Names its upstream and downstream relationships.</li><li>Explains a physiological consequence through its mechanism.</li></ol></article></div><h4>Teaching stations</h4><div class="cl-grid">'+stations.map(([t,id,k,p])=>'<article><h4>'+esc(t)+'</h4><p>'+esc(p)+'</p>'+(offline?'<a href="'+esc(url('study/lesson/'+id))+'">Lesson</a> · <a href="'+esc(url('explorer/'+k.replace('|','/')))+'">3D model</a>':btn('lesson','Open lesson',id)+' '+model(k,'instructor'))+'</article>').join('')+'</div>'+(offline?'':'<div class="cl-pills">'+btn('download-guide','Download instructor guide','','class="cl-primary"')+btn('print-guide','Print guide')+'</div>');
}
